CA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,uBAAuB;AACvB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,uBAAuB;AACvB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,qBAAqB,+BAA+B;AACpD;AACA,yBAAyB,wBAAwB;AACjD,2BAA2B,iCAAiC;AAC5D;AACA,iCAAiC,4BAA4B;AAC7D;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,2BAA2B,uBAAuB;AAClD;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,6BAA6B,6CAA6C;AAC1E;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,qBAAqB;AACrB;AACA;AACA;AACA;AACA;AACA;AACA;AACA,6BAA6B,2CAA2C;AACxE;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,iBAAiB,sCAAsC;AACvD;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,yBAAyB;AACzB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,yBAAyB;AACzB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;;;;;;;;;;;;;;ACniBA;AAAA;AAAA;AAAA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,aAAa;AACb;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,2BAA2B;AAC3B;AACA;AACA,mBAAmB;AACnB;AACA,iBAAiB;AACjB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,6BAA6B;AAC7B;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,+BAA+B;AAC/B;AACA;AACA;AACA;AACA;AACA,mBAAmB;AACnB;AACA,iBAAiB;AACjB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,6BAA6B;AAC7B;AACA;AACA;AACA;AACA,6BAA6B;AAC7B;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,yCAAyC;AACzC;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,2CAA2C;AAC3C;AACA;AACA;AACA;AACA,mCAAmC;AACnC;AACA;AACA;AACA;AACA;AACA;AACA;AACA,2BAA2B;AAC3B;AACA,uBAAuB;AACvB;AACA;AACA;AACA;AACA;AACA;AACA;AACA,WAAW;AACX;AACA;AACA;AACA;AACA;AACA;AACA;;;;;;;;;;;;;;AC1LA;AAAA;AAAA;AAAA;AAAkG;AAC3B;AACL;;;AAGlE;AACsG;AACtG,gBAAgB,2GAAU;AAC1B,EAAE,yFAAM;AACR,EAAE,8FAAM;AACR,EAAE,uGAAe;AACjB;AACA;AACA;AACA;;AAEA;;AAEA;AACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAA2M,CAAgB,uPAAG,EAAC,C;;;;;;;;;;;;ACA/N;AAAA;AAAA;AAAA;AAAA;AAAA;;;;;;;;;;;;;ACAA;AAAA;AAAA;AAAA;AAA+F;AAC3B;AACL;;;AAG/D;AACsG;AACtG,gBAAgB,2GAAU;AAC1B,EAAE,sFAAM;AACR,EAAE,2FAAM;AACR,EAAE,oGAAe;AACjB;AACA;AACA;AACA;;AAEA;;AAEA;AACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAAwM,CAAgB,oPAAG,EAAC,C;;;;;;;;;;;;ACA5N;AAAA;AAAA;AAAA;AAAA;AAAA","file":"chunks/ceres-client-10.js","sourcesContent":["<template>\n    <div class=\"live-shopping-details\">\n        <div class=\"h3 live-shopping-item-name\">\n            <a :href=\"liveShoppingData.item | itemURL\">\n                {{ liveShoppingData.item | itemName }}\n            </a>\n        </div>\n\n        <slot name=\"after-item-name\"></slot>\n\n        <div class=\"live-shopping-countdown\" v-if=\"displaySettings.showTimer || displaySettings.showStock\">\n            <hr class=\"live-shopping-countdown-separator\">\n            <div class=\"live-shopping-countdown-heading\" v-if=\"displaySettings.showTimer\">\n                <div v-if=\"hasStarted\">\n                    {{ $translate(\"Ceres::Template.liveShoppingOfferEndsIn\") }}\n                </div>\n                <div v-else>\n                    {{ $translate(\"Ceres::Template.liveShoppingOfferBeginsIn\") }}\n                </div>\n            </div>\n\n            <div class=\"live-shopping-countdown-thread-container\" v-if=\"displaySettings.showTimer && !!duration\">\n                <div v-if=\"duration.days > 0\" class=\"live-shopping-countdown-thread\">\n                    <div class=\"live-shopping-countdown-thread-number\">{{ duration.days }}</div>\n                    <div class=\"small\">{{ $translate(\"Ceres::Template.liveShoppingDays\") }}</div>\n                </div>\n                <div class=\"live-shopping-countdown-thread\">\n                    <div class=\"live-shopping-countdown-thread-number\">{{ duration.hours }}</div>\n                    <div class=\"small\">{{ $translate(\"Ceres::Template.liveShoppingHours\") }}</div>\n                </div>\n                <div class=\"live-shopping-countdown-thread\">\n                    <div class=\"live-shopping-countdown-thread-number\">{{ duration.minutes }}</div>\n                    <div class=\"small\">{{ $translate(\"Ceres::Template.liveShoppingMinutes\") }}</div>\n                </div>\n                <div v-if=\"duration.days <= 0\" class=\"live-shopping-countdown-thread\">\n                    <div class=\"live-shopping-countdown-thread-number\">{{ duration.seconds }}</div>\n                    <div class=\"small\">{{ $translate(\"Ceres::Template.liveShoppingSeconds\") }}</div>\n                </div>\n            </div>\n\n            <template v-if=\"hasStarted && !hasClosed\">\n                <div class=\"live-shopping-progress\" v-if=\"displaySettings.showTimer && displaySettings.showTimerProgress\">\n                    <div class=\"progress\">\n                        <div :class=\"'progress-' + Math.round(timePercentage / 10) * 10\" class=\"progress-bar\" role=\"progressbar\" :style=\"'width:' + timePercentage + '%'\" aria-valuenow=\"25\" aria-valuemin=\"0\" aria-valuemax=\"100\"></div>\n                    </div>\n                </div>\n\n                <div class=\"live-shopping-progress\" v-if=\"displaySettings.showStock\">\n                    <div class=\"live-shopping-progress-heading\">\n                        <span>{{ $translate(\"Ceres::Template.liveShoppingRemainingStock\", {\"quantityRemaining\": itemQuantityRemaining, \"quantityMax\": liveShoppingData.liveShopping.quantityMax }) }}</span>\n                    </div>\n\n                    <div class=\"progress\" v-if=\"displaySettings.showStockProgress\">\n                        <div :class=\"'progress-' + Math.round(quantitySoldPercentage / 10) * 10\" class=\"progress-bar\" role=\"progressbar\" :style=\"'width:' + quantitySoldPercentage + '%'\" aria-valuenow=\"25\" aria-valuemin=\"0\" aria-valuemax=\"100\"></div>\n                    </div>\n                </div>\n            </template>\n        </div>\n\n        <div class=\"live-shopping-prices bg-danger\" v-if=\"hasStarted && !hasClosed\">\n            <div class=\"live-shopping-prices-inner\">\n                <div class=\"live-shopping-prices-rebate\" v-if=\"!isNaN(itemPriceRebatePercentage) && itemPriceRebatePercentage > 0\">{{ $translate(\"Ceres::Template.liveShoppingRebate\", {\"rebate\": itemPriceRebatePercentage }) }}</div>\n                <div class=\"live-shopping-prices-container\">\n                    <div class=\"live-shopping-price\">\n                        <strong>{{ prices.price.unitPrice.formatted }} *</strong>\n                    </div>\n                    <span v-if=\"isCrossPriceVisible\">\n                        <span v-if=\"prices.isRrpDefaultPrice\" v-html=\"oldPriceBefore\"></span>\n                        <span v-else v-html=\"oldPriceRrp\"></span>\n                    </span>\n                </div>\n            </div>\n\n            <div class=\"live-shopping-prices-additional-info\">\n                <div class=\"live-shopping-lowest-price\" v-if=\"isCrossPriceVisible && liveShoppingData.item.prices.default.lowestPrice.value\">\n                    <span v-html=\"$translate('Ceres::Template.singleItemLowestPrice', {'price': liveShoppingData.item.prices.default.lowestPrice.formatted})\"></span>\n                </div>\n\n                <div class=\"live-shopping-unit-price\" v-if=\"!(liveShoppingData.item.unit.unitOfMeasurement === 'C62' && liveShoppingData.item.unit.content === 1)\">\n                    <span>{{ liveShoppingData.item.unit.content }}</span>\n                    <span>{{ liveShoppingData.item.unit.names.name }}</span>\n                    <span v-if=\"liveShoppingData.item.variation.mayShowUnitPrice\">| {{ prices.price.basePrice }}</span>\n                </div>\n\n                {{ $translate(\"Ceres::Template.liveShoppingFootnote\") }} <template v-if=\"showNetPrices\">{{ $translate(\"Ceres::Template.itemExclVAT\") }}</template><template v-else>{{ $translate(\"Ceres::Template.itemInclVAT\") }}</template> {{ $translate(\"Ceres::Template.itemExclusive\") }}\n                <a v-if=\"$ceres.config.global.shippingCostsCategoryId > 0\" data-toggle=\"modal\" href=\"#shippingscosts\" :title=\"$translate('Ceres::Template.itemShippingCosts')\">{{ $translate(\"Ceres::Template.itemShippingCosts\") }}</a>\n                <a v-else :title=\"$translate('Ceres::Template.itemShippingCosts')\">{{ $translate(\"Ceres::Template.itemShippingCosts\") }}</a>\n            </div>\n        </div>\n\n        <div class=\"thumb-content\" v-else>\n            <div>\n                <div class=\"prices\">\n                    <div class=\"price-view-port\">\n                        <del class=\"crossprice\" v-if=\"isCrossPriceVisible\">\n                            {{ prices.rrp.price.formatted | itemCrossPrice  }}\n                        </del>\n                    </div>\n\n                    <div class=\"price\">\n                        {{ prices.price.price.formatted }} *\n                    </div>\n                </div>\n\n                <div class=\"category-lowest-price small\" v-if=\"isCrossPriceVisible && liveShoppingData.item.prices.default.lowestPrice.value\">\n                    <span v-html=\"$translate('Ceres::Template.singleItemLowestPrice', {'price': liveShoppingData.item.prices.default.lowestPrice.formatted})\"></span>\n                </div>\n\n                <div class=\"category-unit-price small\" v-if=\"!(liveShoppingData.item.unit.unitOfMeasurement === 'C62' && liveShoppingData.item.unit.content === 1)\">\n                    <span>{{ liveShoppingData.item.unit.content }}</span>\n                    <span>{{ liveShoppingData.item.unit.names.name }}</span>\n                    <span v-if=\"liveShoppingData.item.variation.mayShowUnitPrice\">| {{ prices.price.basePrice }}</span>\n                </div>\n\n                <span class=\"vat small text-muted\">\n                    {{ $translate(\"Ceres::Template.liveShoppingFootnote\") }} <template v-if=\"showNetPrices\">{{ $translate(\"Ceres::Template.itemExclVAT\") }}</template><template v-else>{{ $translate(\"Ceres::Template.itemInclVAT\") }}</template> {{ $translate(\"Ceres::Template.itemExclusive\") }}\n                    <a v-if=\"$ceres.config.global.shippingCostsCategoryId > 0\" data-toggle=\"modal\" href=\"#shippingscosts\" :title=\"$translate('Ceres::Template.itemShippingCosts')\">{{ $translate(\"Ceres::Template.itemShippingCosts\") }}</a>\n                    <a v-else :title=\"$translate('Ceres::Template.itemShippingCosts')\">{{ $translate(\"Ceres::Template.itemShippingCosts\") }}</a>\n                </span>\n            </div>\n        </div>\n\n    </div>\n</template>\n\n<script>\nimport dayjs from \"dayjs\";\n\nexport default {\n    props:\n    {\n        liveShoppingData:\n        {\n            type: Object,\n            required: true\n        },\n\n        displaySettings:\n        {\n            type: Object,\n            default: () =>\n            {\n                return {\n                    showCrossPrice: true,\n                    showStock: true,\n                    showStockProgress: true,\n                    showTimer: true,\n                    showTimerProgress: true\n                };\n            }\n        },\n\n        prices:\n        {\n            type: Object,\n            required: true\n        },\n\n        isActiveByStock:\n        {\n            type: Boolean\n        },\n\n        showNetPrices:\n        {\n            type: Boolean\n        }\n    },\n\n    data()\n    {\n        return {\n            currentInterval: null,\n            duration: null,\n            hasClosed: null,\n            hasStarted: null,\n            itemPriceRebatePercentage: 0,\n            itemQuantityRemaining: 0,\n            momentBegin: null,\n            momentEnd: null,\n            quantitySoldPercentage: 0,\n            timePercentage: 0\n        };\n    },\n\n    computed:\n    {\n        oldPriceBefore()\n        {\n            return this.$translate('Ceres::Template.liveShoppingBefore', {'price': '<del>' + this.prices.rrp.unitPrice.formatted + '</del>'})\n        },\n\n        oldPriceRrp()\n        {\n            return this.$translate('Ceres::Template.liveShoppingRrp', {'price': '<del>' + this.prices.rrp.unitPrice.formatted + '</del>'})\n        },\n\n        isCrossPriceVisible()\n        {\n            return this.displaySettings.showCrossPrice && this.prices.rrp && this.prices.rrp.unitPrice.value > 0;\n        }\n    },\n\n    created()\n    {\n        this.initializeDataAndTimer();\n    },\n\n    methods:\n    {\n        initializeDataAndTimer()\n        {\n            const momentNow = dayjs();\n\n            this.momentBegin = dayjs.unix(this.liveShoppingData.liveShopping.fromTime);\n            this.momentEnd = dayjs.unix(this.liveShoppingData.liveShopping.toTime);\n            this.hasStarted = this.momentBegin.valueOf() < momentNow.valueOf();\n            this.hasClosed = this.momentEnd.valueOf() < momentNow.valueOf();\n\n            this.setQuantitySoldPercentage();\n\n            if (this.hasStarted && !this.hasClosed)\n            {\n                this.setItemPriceRebatePercentage();\n            }\n\n            clearInterval(this.currentInterval);\n\n            this.calculations();\n            this.currentInterval = setInterval(() =>\n            {\n                this.calculations();\n            }, 1000);\n        },\n\n        setQuantitySoldPercentage()\n        {\n            const data            = this.liveShoppingData.liveShopping;\n            const percentage      = 100 - data.quantitySold / data.quantityMax * 100;\n\n            this.itemQuantityRemaining = data.quantityMax - data.quantitySold;\n            this.quantitySoldPercentage = percentage.toFixed(App.config.item.storeSpecial);\n        },\n\n        setItemPriceRebatePercentage()\n        {\n            const specialOfferPrice = this.prices.price.price.value;\n            const defaultPrice      = this.prices.rrp && this.prices.rrp.price.value || 0;\n\n            if (defaultPrice === 0)\n            {\n                this.itemPriceRebatePercentage = 0;\n            }\n            else\n            {\n                let percentage          = 100 - specialOfferPrice / defaultPrice * 100;\n\n                percentage = percentage.toFixed(App.config.item.storeSpecial);\n                percentage = percentage.replace(\".\", App.decimalSeparator);\n\n                this.itemPriceRebatePercentage = percentage;\n            }\n\n        },\n\n        calculations()\n        {\n            const momentNow = dayjs();\n            let fullSeconds = 0;\n            let remainSeconds = 0;\n\n            fullSeconds = this.momentEnd.diff(this.momentBegin, \"second\");\n            if (this.hasStarted)\n            {\n                remainSeconds = this.momentEnd.diff(momentNow, \"second\");\n            }\n            else\n            {\n                remainSeconds = this.momentBegin.diff(momentNow, \"second\");\n            }\n\n            this.timePercentage = (remainSeconds / fullSeconds * 100).toFixed(App.config.item.storeSpecial);\n            this.duration = this.getDuration(remainSeconds);\n\n            const hasToStart = !this.hasStarted && this.momentBegin < momentNow;\n            const hasToClose = !this.hasClosed && this.momentEnd < momentNow;\n\n            if (hasToStart || hasToClose)\n            {\n                clearInterval(this.currentInterval);\n\n                this.$emit(\"reload-offer\");\n            }\n        },\n\n        getDuration(seconds)\n        {\n            const days = Math.floor(seconds / (60 * 60 * 24));\n\n            seconds = seconds - (days * 60 * 60 * 24);\n\n            const hours = Math.floor(seconds / (60 * 60));\n\n            seconds = seconds - (hours * 60 * 60);\n\n            const minutes = Math.floor(seconds / 60);\n\n            seconds = seconds - (minutes * 60);\n\n            return {\n                days: days,\n                hours: hours,\n                minutes: minutes,\n                seconds: seconds\n            };\n        }\n    },\n\n    watch:\n    {\n        liveShoppingData()\n        {\n            this.initializeDataAndTimer();\n        }\n    }\n}\n</script>\n","<template>\n    <div>\n        <category-item\n                v-if=\"!!currentOffer\"\n                :item-data=\"currentOffer.item\"\n                :decimal-count=\"$ceres.config.item.storeSpecial\"\n                image-url-accessor=\"urlMiddle\"\n                :padding-classes=\"paddingClasses\"\n                :padding-inline-styles=\"paddingInlineStyles\"\n                :force-url-with-variation-id=\"true\">\n            <template #store-special>\n                <item-store-special v-if=\"!!storeSpecial\"\n                                    :store-special=\"storeSpecial\"\n                                    :recommended-retail-price=\"prices.rrp\"\n                                    :variation-retail-price=\"prices.price\"\n                                    :decimal-count=\"$ceres.config.item.storeSpecial \">\n                </item-store-special>\n            </template>\n            <template #item-image>\n                <a v-if=\"!!displaySettings.customImagePath\" :href=\"currentOffer.item | itemURL\">\n                    <lazy-img   :image-url=\"displaySettings.customImagePath\"\n                                :alt=\"